function codepoint(glyph) {
    if (!glyph) return "";
    var cps = [];
    for (var i = 0; i < glyph.length; i++) {
        var cp = glyph.codePointAt(i);
        cps.push("U+" + cp.toString(16).toUpperCase());
        if (cp > 0xFFFF) i++;
    }
    return cps.join(" ");
}

function matches(query, category) {
    var q = query ? query.trim().toLowerCase() : "";
    var hasCat = (category && category !== "all");

    if (!q && !hasCat) {
        return EMOJI;
    }

    return EMOJI.filter(function(e) {
        if (hasCat && e[2] !== category) {
            return false;
        }
        if (!q) {
            return true;
        }
        return e[0].toLowerCase().indexOf(q) !== -1 || e[3].toLowerCase().indexOf(q) !== -1 || e[1] === q;
    });
}
